class BriefingState(rx.State):
    """Statements of the open offer, grouped by type."""

    groups: rx.Field[list[dict[str, Any]]] = rx.field(default_factory=list)

    @rx.var
    def is_empty(self) -> bool:
        return not self.groups

    async def _reload(self, offer_id: int) -> None:
        async with get_asyncdb_session() as session:
            self.groups = await load_briefing(session, offer_id)

    @rx.event
    @requires_offer_editor
    async def load_briefing(self) -> AsyncGenerator[Any]:
        offer_id = await open_offer_id(self)
        if not offer_id:
            return
        try:
            await self._reload(offer_id)
        except Exception:
            logger.exception("Loading the briefing of offer %s failed", offer_id)
            yield rx.toast.error(LOAD_ERROR, position="top-right")

    @rx.event
    @requires_offer_editor
    async def confirm(self, statement_id: int, confirmed: bool) -> AsyncGenerator[Any]:
        """Confirm a statement as a professional decision, or withdraw it."""
        offer_id = await open_offer_id(self)
        if not offer_id:
            return
        try:
            found = await set_confirmed(
                get_asyncdb_session,
                offer_id,
                statement_id,
                confirmed=confirmed,
                user=await current_user_name(self),
            return failed
        self.save_label = SAVED
        if isinstance(content, TableContent):
            # A table needs neither the map nor the values to show itself.
            self.revision = revision
            self._content = content.model_dump(mode="json")
            self._touch(key, revision, render_block(content, (), {}))
        else:
            await self._reload(service)
        return None

    async def _load_active(self, service: ChapterService) -> None:
        loaded = await service.load(self.active_key)
        self._content = loaded["content"]
        content = parse_content(loaded["content"])
        self.revision = loaded["revision"]
        self.origin = loaded["origin"]
        self.proposal = loaded["proposal"] or {}
        self.editable = editor_compatible(content)
        self.editor_html = content_to_html(content) if self.editable else ""
        prose = self.active.get("type", "prose") == "prose"
        self.note = UNSUPPORTED_NOTE if prose and not self.editable else ""
        # Only another chapter or revision remounts the editor; a reload while
        # somebody types keeps the cursor.
        shown = f"{self.active_key}:{self.revision}"
        if shown != self._editor_for:
            self._editor_for = shown
            self.editor_nonce += 1
        self.save_label = ""

    async def _reload(
        self, service: ChapterService, *, select_first: bool = False
    ) -> None:
        """Document, frame and removed chapters; the selection stays if it can."""
        document = await load_document(
            get_asyncdb_session, service.offer_id, service.user
        )
        if document is None:
            return
        self.chapters = document.chapters
        self.frame_before = document.frame_before
        self.frame_after = document.frame_after
        self.removed_chapters = await self._outline_for(service).removed()
        keys = [c["key"] for c in self.chapters]
        if self.active_key not in keys:
            # A removed chapter leaves nothing selected; a new page starts at 1.
            self.active_key = keys[0] if select_first and keys else ""
        if self.active_key:
            await self._load_active(service)
        async with get_asyncdb_session() as session:
            job = await job_repo.find_latest(
                session, service.offer_id, DRAFT_CHAPTERS_JOB
            )
        self.draft_job = job.status if job is not None else ""

    @rx.event
    @requires_offer_editor
    async def load_chapters(self) -> AsyncGenerator[Any]:
        """Load the chapters; creates them from the template on first use."""
        service = await self._service()
        if service is None:
            return
        try:
            await self._reload(service, select_first=True)
        except Exception:
            logger.exception(
                "Loading the chapters of offer %s failed", service.offer_id
            )
            yield rx.toast.error(LOAD_ERROR, position="top-right")

    @rx.event
    @requires_offer_editor
    async def refresh_drafts(self) -> AsyncGenerator[Any]:
        """Poll while the AI works; reloads once, when the job has finished."""
        service = await self._service()
        if service is None:
            return
        offer_id = service.offer_id
        before = self.draft_job
        async with get_asyncdb_session() as session:
            job = await job_repo.find_latest(session, offer_id, DRAFT_CHAPTERS_JOB)
        status = job.status if job is not None else ""
        if status in WORKING:
            return
        self.draft_job = status
        if before in WORKING:
            try:
                await self._reload(service)
            except Exception:
                logger.exception("Reloading chapters of offer %s failed", offer_id)
                yield rx.toast.error(LOAD_ERROR, position="top-right")

    @rx.event
    @requires_offer_editor
    async def select_chapter(self, key: str) -> AsyncGenerator[Any]:
        """A click on a block makes it the one being edited."""
        yield await self._select(key)

    async def _select(self, key: str) -> Any | None:
        service = await self._service()
        if service is None or key == self.active_key:
            return None
        self.active_key = key
        self.history_open = False
        try:
            await self._load_active(service)
    @rx.var
    def general_findings(self) -> list[dict[str, Any]]:
        return [f for f in self.findings if not f["target"].startswith(CHAPTER_PREFIX)]

    @rx.var
    def blocker_count(self) -> int:
        return sum(
            1
            for f in self.findings
            if f["severity"] == FindingSeverity.BLOCKER
            and f["decision"] == FindingDecision.OPEN
        )

    @rx.var
    def reviewing(self) -> bool:
        return self.review_job in WORKING

    async def _reload(self, offer_id: int) -> None:
        self.findings = await findings.list_findings(get_asyncdb_session, offer_id)
        view = await commercials.load_view(get_asyncdb_session, offer_id)
        self.calc_rows = view.rows
        self.calc_confirmed = view.confirmed
        self.calc_confirmed_by = view.confirmed_by
        self.calc_confirmed_at = view.confirmed_at
        self.price_required = view.price_required
        self.validity_date = view.validity_date
        async with get_asyncdb_session() as session:
            job = await job_repo.find_latest(session, offer_id, REVIEW_JOB)
        self.review_job = job.status if job is not None else ""

    async def _guarded(self, action: Any, error: str) -> Any | None:
        """Run a service call and reload; a toast comes back on failure."""
        offer_id = await open_offer_id(self)
        if not offer_id:
            return None
        try:
            await action(offer_id)
            await self._reload(offer_id)
        except (findings.FindingError, commercials.CommercialsError) as exc:
            return rx.toast.error(str(exc), position="top-right")
        except Exception:
            logger.exception("Review action for offer %s failed", offer_id)
            return rx.toast.error(error, position="top-right")
        return None

    @rx.event
    @requires_offer_editor
    async def run_checks(self) -> AsyncGenerator[Any]:
        """Run the rule checks and load findings; also runs when the tab opens."""
        toast = await self._guarded(
            lambda offer_id: findings.run_checks(get_asyncdb_session, offer_id),
            LOAD_ERROR,
        )
        if toast:
            yield toast

    @rx.event
    @requires_offer_editor
    async def request_ai_review(self) -> AsyncGenerator[Any]:
        offer_id = await open_offer_id(self)
        if not offer_id or self.reviewing:
            return
        config = service_registry().get(WorkshopConfig)
        try:
            await request_review(
                get_asyncdb_session,
                offer_id,
                now=datetime.now(UTC),
                max_attempts=config.max_attempts,
            )
            self.review_job = JobStatus.QUEUED
            yield rx.toast.info(REVIEW_QUEUED, position="top-right")
        except ReviewNotPossibleError as exc:
            yield rx.toast.error(str(exc), position="top-right")
        except Exception:
            logger.exception("Queueing the review of offer %s failed", offer_id)
            yield rx.toast.error(REVIEW_ERROR, position="top-right")

    @rx.event
    @requires_offer_editor
    async def refresh_review(self) -> AsyncGenerator[Any]:
        """Poll while the AI works; reloads once when the job has finished."""
        offer_id = await open_offer_id(self)
        if not offer_id:
            return
        async with get_asyncdb_session() as session:
            job = await job_repo.find_latest(session, offer_id, REVIEW_JOB)
        status = job.status if job is not None else ""
        if status in WORKING:
            return
        was_working = self.reviewing
        self.review_job = status
        if was_working:
            try:
                await self._reload(offer_id)
            except Exception:
                logger.exception("Reloading findings of offer %s failed", offer_id)
                yield rx.toast.error(LOAD_ERROR, position="top-right")

