            parse_content(stored[c.id].content), stories, values
        )
        for c in chapters
    }
    return OfferDocument(
        chapters=[{**view, **blocks.get(view["key"], {})} for view in views],
        frame_before=template.frame_before,
        frame_after=template.frame_after,
    )

