async def _sources_stage(session: AsyncSession, offer_id: int) -> str:
    rows = [s for s in await source_repo.list_current(session, offer_id) if s.included]
    if not rows:
        return OPEN
    if any(s.status in (SourceStatus.UPLOADED, SourceStatus.PROCESSING) for s in rows):
        return RUNNING
    return DONE


async def _stages(session: AsyncSession, offer_id: int) -> list[dict[str, str]]:
    """Sources stage plus the latest job of each pipeline stage, in one query."""
    kinds = [kind for _, kind in JOB_STAGES]
    latest = (
        select(func.max(JobEntity.id))
        .where(JobEntity.offer_id == offer_id, JobEntity.kind.in_(kinds))
        .group_by(JobEntity.kind)
    )
    rows = await session.execute(
        select(JobEntity.kind, JobEntity.status).where(JobEntity.id.in_(latest))
    )
    status_of = {kind: JOB_STATES.get(status, OPEN) for kind, status in rows.all()}
    stages = [
        {"label": SOURCES_STAGE, "status": await _sources_stage(session, offer_id)}
    ]
    stages.extend(
        {"label": label, "status": status_of.get(kind, OPEN)}
        for label, kind in JOB_STAGES
    )
    return stages


